	const (
		minGrace = 120 * time.Second
		maxGrace = 2 * time.Hour
	)
	if period <= 0 {
		return minGrace
	}
	grace := period / 2
	if grace < minGrace {
		return minGrace
	}
	if grace > maxGrace {
		return maxGrace
	}
	return grace
}

